/**
 * Sticker-style icon set (generated by the icons codemod; safe to edit).
 *
 * Every icon the app uses is re-exported from here as a chunky, colour-filled
 * glyph with a bold outline, matching the flat "sticker" icon sheet in the
 * design brief. Callers keep passing `color` (it drives the outline, so
 * contrast on dark/lime surfaces still works) and may pass `fill` to
 * override the sticker colour (e.g. `fill="none"` for an un-liked heart).
 */
import React from 'react';
import * as L from 'lucide-react-native';
import type { LucideIcon, LucideProps } from 'lucide-react-native';

export type { LucideIcon, LucideProps };

export const STICKER = {
  blue: '#1E9BFF',
  green: '#3DDC4A',
  orange: '#FF7A2F',
  pink: '#FF8FB1',
  yellow: '#FFC21A',
  red: '#FF5A36',
} as const;
export type StickerColor = keyof typeof STICKER;

const INK = '#14180F';

export function sticker(Icon: LucideIcon, tone: StickerColor | null): LucideIcon {
  const Wrapped = ({ color, strokeWidth, fill, ...rest }: LucideProps) => (
    <Icon {...rest} color={color ?? INK} fill={fill ?? (tone ? STICKER[tone] : 'none')} strokeWidth={strokeWidth ?? 2.2} strokeLinejoin="round" strokeLinecap="round" />
  );
  Wrapped.displayName = `Sticker(${Icon.displayName ?? 'Icon'})`;
  return Wrapped as unknown as LucideIcon;
}

